diff --git a/src/cache.js b/src/cache.js
index 1111111..2222222 100644
--- a/src/cache.js
+++ b/src/cache.js
@@ -1,3 +1,7 @@
-function get(key) {
-  return db.query('SELECT v FROM kv WHERE k=?', key);
-}
+const memo = new Map();
+function get(key) {
+  if (memo.has(key)) return memo.get(key);
+  const v = db.query('SELECT v FROM kv WHERE k=?', key);
+  memo.set(key, v);
+  return v;
+}
